export class DynamicResourceAllocator {
  constructor(sharedPool) {
    this.sharedPool = sharedPool;
    this.priorityQueue = [];
  }

  requestResources(agentId, amount, priority) {
    this.priorityQueue.push({ agentId, amount, priority });
    this.priorityQueue.sort((a, b) => b.priority - a.priority);
    this.allocateResources();
  }

  releaseResources(agentId, amount) {
    this.sharedPool[agentId] = (this.sharedPool[agentId] || 0) - amount;
    if (this.sharedPool[agentId] < 0) this.sharedPool[agentId] = 0;
  }

  allocateResources() {
    while (this.priorityQueue.length > 0) {
      const { agentId, amount, priority } = this.priorityQueue.shift();
      if (this.sharedPool[agentId] + amount <= this.sharedPool.total) {
        this.sharedPool[agentId] = (this.sharedPool[agentId] || 0) + amount;
      }
    }
  }
}

